var countServers = function(n, logs, x, queries) {
    logs.sort((a, b) => a[1] - b[1]);
    const order = [...queries.keys()].sort((a, b) => queries[a] - queries[b]);
    const cnt = new Map();
    let active = 0, l = 0, r = 0;
    const res = new Array(queries.length);
    for (const qi of order) {
        const q = queries[qi];
        while (r < logs.length && logs[r][1] <= q) {
            const sid = logs[r][0];
            cnt.set(sid, (cnt.get(sid) || 0) + 1);
            if (cnt.get(sid) === 1) active++;
            r++;
        }
        while (l < r && logs[l][1] < q - x) {
            const sid = logs[l][0];
            cnt.set(sid, cnt.get(sid) - 1);
            if (cnt.get(sid) === 0) { active--; cnt.delete(sid); }
            l++;
        }
        res[qi] = n - active;
    }
    return res;
};
